from flask import Flask, request, render_template_string

app = Flask(__name__)

@app.route('/chat')
def chat():
    message = request.args.get('message')

    template = '''
    <h1>Chat</h1>
    <p>{}</p>
    '''.format(message)

    return render_template_string(template)

